const body = $json.body ?? $json;
const productName = String(body.product_name ?? '').trim();
if (!productName) throw new Error('product_name الزامی است');
const city = String(body.location?.city ?? body.city ?? 'اصفهان').trim();
const area = String(body.location?.area ?? body.area ?? 'کل شهر').trim();

const safeNumber = (value, fallback, min, max) => {
  const n = Number(value ?? fallback);
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;
};
const centerLat = safeNumber(body.location?.latitude ?? body.latitude, 32.6546, 24, 40);
const centerLong = safeNumber(body.location?.longitude ?? body.longitude, 51.6680, 44, 64);
const latStep = safeNumber(body.location?.lat_step, 0.050, 0.010, 0.100);
const longStep = safeNumber(body.location?.long_step, 0.050, 0.010, 0.100);
const pageSize = Math.round(safeNumber(body.page_size, 36, 1, 100));
const maxPages = Math.round(safeNumber(body.max_pages, 30, 1, 50));

const offsets = [2, 1, 0, -1, -2];
const rowLabel = dy => dy === 2 ? 'شمال دور' : dy === 1 ? 'شمال' : dy === 0 ? 'مرکز' : dy === -1 ? 'جنوب' : 'جنوب دور';
const colLabel = dx => dx === -2 ? 'غرب دور' : dx === -1 ? 'غرب' : dx === 0 ? 'مرکز' : dx === 1 ? 'شرق' : 'شرق دور';
const points = [];
for (let r = 0; r < offsets.length; r++) {
  for (let c = 0; c < offsets.length; c++) {
    const dy = offsets[r], dx = offsets[c];
    points.push({
      key: 'R' + (r + 1) + 'C' + (c + 1),
      label: rowLabel(dy) + ' - ' + colLabel(dx),
      dy, dx
    });
  }
}
return points.map((p, index) => ({ json: {
  product_name: productName, city, area,
  point_id: p.key, point_label: p.label, point_index: index + 1,
  latitude: Number((centerLat + p.dy * latStep).toFixed(6)),
  longitude: Number((centerLong + p.dx * longStep).toFixed(6)),
  page_size: pageSize, max_pages: maxPages,
  requested_at: new Date().toISOString()
}}));

const inputItems = $input.all();
const norm = v => String(v ?? '').toLowerCase().normalize('NFKC')
  .replace(/[يى]/g,'ی').replace(/ك/g,'ک')
  .replace(/[\u064B-\u065F\u0670]/g,'')
  .replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
  .replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const tokens = v => norm(v).split(/\s+/).filter(Boolean);
const stop = new Set(['و','با','برای','از','در','عدد','بسته','محصول','گرم','گرمی','کیلوگرم','کیلو']);
const numeric = v => Number.isFinite(Number(v)) ? Number(v) : null;
const storeMap = new Map(), offerMap = new Map(), pointStats = new Map();
let reportedVendors=0, reportedProducts=0, validPages=0;
let requestedProduct='', city='اصفهان';
for (const item of inputItems) {
  const j = item.json ?? {};
  const point = {
    id:j.point_id ?? j.api_response?.point_id ?? 'unknown',
    label:j.point_label ?? '',
    latitude:j.latitude ?? null, longitude:j.longitude ?? null
  };
  const api = j.api_response ?? j.body ?? j;
  const data = api?.data?.vendor_product_variations;
  if (!data || !Array.isArray(data.items)) continue;
  validPages++;
  requestedProduct = requestedProduct || j.product_name || '';
  city = j.city || city;
  reportedVendors = Math.max(reportedVendors, Number(data.total_vendor || 0));
  reportedProducts = Math.max(reportedProducts, Number(data.total_product || 0));
  const ps = pointStats.get(point.id) || {point_id:point.id,point_label:point.label,latitude:point.latitude,longitude:point.longitude,pages:0,vendors_seen:0,products_seen:0};
  ps.pages++; ps.vendors_seen += data.items.length;
  for (const store of data.items) {
    const storeId = String(store.id ?? store.vendor_id ?? '');
    const storeCode = String(store.code ?? store.vendor_code ?? '');
    const storeName = store.title ?? store.name ?? '';
    const address = store.address ?? store.full_address ?? store.location?.address ?? null;
    const storeKey = storeCode || storeId || norm(storeName)+'|'+norm(address);
    const isOpen = store.is_open ?? null;
    const canDeliver = store.does_deliver ?? store.deliver ?? null;
    const category = isOpen === true ? (canDeliver === true ? 'باز و دارای ارسال' : canDeliver === false ? 'باز و فاقد ارسال' : 'باز؛ ارسال نامشخص')
      : isOpen === false ? (canDeliver === true ? 'بسته و دارای اطلاعات ارسال' : canDeliver === false ? 'بسته و فاقد ارسال' : 'بسته؛ ارسال نامشخص') : 'وضعیت نامشخص';
    if (!storeMap.has(storeKey)) storeMap.set(storeKey,{
      store_code:storeCode || null,store_code:storeCode || null,store_id:storeId || null,store_name:storeName,area:store.area ?? store.district ?? store.neighborhood ?? null,
      address,is_open:isOpen,store_status:isOpen === true?'باز':isOpen === false?'بسته':'نامشخص',
      can_deliver:canDeliver,delivery_status:canDeliver === true?'دارد':canDeliver === false?'ندارد':'نامشخص',
      store_category:category,seen_at_points:[]
    });
    const s = storeMap.get(storeKey);
    if (!s.seen_at_points.some(x=>x.point_id===point.id)) s.seen_at_points.push(point);
    for (const p of (Array.isArray(store.products)?store.products:[])) {
      const title = p.title ?? p.name ?? '';
      const price = numeric(p.price), discount = numeric(p.discount ?? 0);
      if (!title || price === null || price <= 0 || discount === null) continue;
      const wanted = tokens(requestedProduct).filter(t=>!stop.has(t));
      const actual = tokens(title);
      const matched = wanted.filter(t=>actual.some(x=>x===t || (t.length>=4 && x.includes(t)) || (x.length>=4 && t.includes(x)))).length;
      const score = wanted.length ? matched/wanted.length : 0;
      const exact = norm(title).includes(norm(requestedProduct));
      const brand = p.brand?.title ?? p.brand_name ?? (typeof p.brand==='string'?p.brand:null);
      // اگر کاربر وزن/حجم مشخص کرده، محصول با بسته‌بندی متفاوت نباید match قطعی شود.
      const sizeOf = value => {
        const raw = String(value ?? '').toLowerCase().replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[يى]/g,'ی').replace(/ك/g,'ک');
        const m = raw.match(/(\d+(?:[.,]\d+)?)\s*(کیلوگرمی|کیلوگرم|کیلو|گرمی|گرم|میلیلیتری|میلی\s*لیتر|میلیلیتر|لیتری|لیتر|kg|g|ml|l)/i);
        if (!m) return null;
        const n = Number(m[1].replace(',','.')), u = m[2];
        if (/^(کیلوگرمی|کیلوگرم|کیلو|kg)$/i.test(u)) return Math.round(n*1000);
        if (/^(گرمی|گرم|g)$/i.test(u)) return Math.round(n);
        if (/^(لیتری|لیتر|l)$/i.test(u)) return Math.round(n*1000);
        return Math.round(n);
      };
      const wantedSize = sizeOf(requestedProduct), actualSize = sizeOf(title);
      const sizeMismatch = wantedSize !== null && actualSize !== null && wantedSize !== actualSize;
      // دسته اصلی کالا باید با عبارت کاربر سازگار باشد؛ مثلا «سس گوجه» جای «رب گوجه» ننشیند.
      // اگر برند در عبارت درخواست آمده، فقط همان برند مجاز است.
      const brandTokens = brand && norm(requestedProduct).includes(norm(brand)) ? tokens(brand) : [];
      const categoryTokens = tokens(title);
      const coreTokens = wanted.filter(t => !/^\d+(?:\.\d+)?$/.test(t) && !brandTokens.includes(t));
      const categoryMismatch = coreTokens.some(t => !categoryTokens.includes(t));
      const matchStatus = sizeMismatch || categoryMismatch ? 'نامرتبط' : exact ? 'مرتبط' : score >= 0.95 ? 'مرتبط' : score >= 0.60 ? 'نیازمند بازبینی' : 'نامرتبط';
      if (matchStatus==='نامرتبط') continue;
      const productId = String(p.id ?? p.product_id ?? p.variation_id ?? '');
      const packageSize = p.weight ?? p.volume ?? p.size ?? p.package_size ?? null;
      const packageText = (title.match(/\d+(?:[.,]\d+)?\s*(?:کیلوگرم|کیلو|گرم|میلی.?لیتر|لیتر)/i)||[])[0] || '';
      const packCount = (title.match(/(?:بسته\s*)?(\d+)\s*عددی/i)||[])[1] || '';
      const identity = productId || norm(title)+'|'+String(packageSize ?? packageText)+'|'+packCount;
      const key = storeKey+'|'+identity;
      if (!offerMap.has(key)) offerMap.set(key,{
        store_code:storeCode || null,store_id:storeId || null,store_name:storeName,area:store.area ?? store.district ?? store.neighborhood ?? null,address,
        store_status:isOpen===true?'باز':isOpen===false?'بسته':'نامشخص',is_open:isOpen,
        delivery_status:canDeliver===true?'دارد':canDeliver===false?'ندارد':'نامشخص',can_deliver:canDeliver,store_category:category,
        product_id:productId || null,product_title:title,brand,package_size:(packageSize ?? packageText) || null,
        pack_count:packCount ? Number(packCount):null,original_price:price,discount,final_price:price-discount,
        stock:p.stock ?? p.quantity ?? null,stock_status:p.stock==null?'نامشخص':Number(p.stock)>0?'موجود':'ناموجود',
        relevance:matchStatus,relevance_score:Number(score.toFixed(3)),seen_at_points:[]
      });
      const offer = offerMap.get(key);
      if (!offer.seen_at_points.some(x=>x.point_id===point.id)) offer.seen_at_points.push(point);
      // بهترین تطبیق/قیمت آخرین پاسخ نگه داشته می‌شود؛ برای یک SKU از چند نقطه، قیمت یکسان انتظار می‌رود.
      if (score > offer.relevance_score) { offer.relevance_score=Number(score.toFixed(3)); offer.relevance=matchStatus; }
    }
  }
  pointStats.set(point.id,ps);
}
if (!requestedProduct) throw new Error('نام محصول درخواستی به مرحله تطبیق نرسیده است؛ انتقال metadata از Search را بررسی کنید.');
const codeSort=(a,b)=>{
  const aa=String(a.store_code??''),bb=String(b.store_code??'');
  const an=Number(aa),bn=Number(bb);
  if (Number.isFinite(an)&&Number.isFinite(bn)) return an-bn;
  return aa.localeCompare(bb,'en',{numeric:true});
};
const stores=[...storeMap.values()].sort(codeSort);
const offers=[...offerMap.values()].sort((a,b)=>codeSort(a,b)||String(a.product_title).localeCompare(String(b.product_title),'fa'));
const points=[...pointStats.values()].sort((a,b)=>String(a.point_id).localeCompare(String(b.point_id)));
const rows=offers.map(o=>({
  'کد فروشگاه':o.store_code,'شناسه فروشگاه':o.store_id,'نام فروشگاه':o.store_name,'منطقه':o.area,'آدرس':o.address,
  'وضعیت فروشگاه':o.store_status,'ارسال':o.delivery_status,'دسته وضعیت':o.store_category,
  'کد محصول':o.product_id,'نام محصول':o.product_title,'برند':o.brand,'وزن/حجم':o.package_size,'تعداد بسته':o.pack_count,
  'قیمت اصلی':o.original_price,'تخفیف':o.discount,'قیمت نهایی':o.final_price,
  'موجودی':o.stock,'وضعیت موجودی':o.stock_status,'تطبیق':o.relevance,'امتیاز تطبیق':o.relevance_score,
  'نقاط مشاهده':o.seen_at_points.map(p=>p.label+' ('+p.id+')').join('، ')
}));
const summary={
  success:true,requested_product:requestedProduct,city,
  points_requested:25,points_with_results:points.length,pages_received:validPages,
  reported_total_vendors_max_per_point:reportedVendors,reported_total_products_max_per_point:reportedProducts,
  unique_stores:stores.length,unique_offers:offers.length,
  needs_review:offers.filter(x=>x.relevance==='نیازمند بازبینی').length,
  open_with_delivery:offers.filter(x=>x.store_category==='باز و دارای ارسال').length,
  open_without_delivery:offers.filter(x=>x.store_category==='باز و فاقد ارسال').length,
  closed:offers.filter(x=>x.store_status==='بسته').length,
  unknown_store_status:offers.filter(x=>x.store_status==='نامشخص').length
};
return rows.length ? rows.map(row => ({ json: row })) : [{ json: { 'نتیجه': 'محصول مرتبطی پیدا نشد', 'محصول درخواستی': requestedProduct, 'شهر': city, 'تعداد نقاط بررسی‌شده': points.length, 'تعداد صفحات دریافت‌شده': validPages } }];

const responses = $input.all();
const points = $('Generate 25 Isfahan Search Points').all();

return responses.map((item, index) => {
  // n8n may emit one item per HTTP page or one final item per search point.
  // Prefer item linking when present; fall back to positional pairing only for 1:1 output.
  const link = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  let pointIndex = Number.isInteger(link?.item) ? link.item : null;
  if (pointIndex === null) {
    if (responses.length !== points.length) {
      throw new Error('تعداد پاسخ‌های صفحه‌بندی‌شده با نقاط جست‌وجو برابر نیست و ارتباط آیتم‌ها هم موجود نیست؛ برای جلوگیری از انتساب اشتباه متوقف شد.');
    }
    pointIndex = index;
  }

  const point = points[pointIndex]?.json;
  if (!point) throw new Error(`اطلاعات نقطه شماره ${pointIndex + 1} پیدا نشد.`);
  const raw = item.json ?? {};
  const api = raw.api_response ?? raw.body ?? raw;
  if (!api?.data?.vendor_product_variations || !Array.isArray(api.data.vendor_product_variations.items)) {
    throw new Error(`ساختار پاسخ API برای نقطه ${point.point_id} معتبر نیست.`);
  }
  return {
    json: {
      ...point,
      api_response: api,
      api_page: api.pagination?.page ?? null,
      api_status: api.status ?? null
    },
    pairedItem: { item: index }
  };
});
